import numpy as np
import os

# Load experiment data
working_dir = os.path.join(os.getcwd(), "working")
experiment_data_file = os.path.join(working_dir, "experiment_data.npy")
experiment_data = np.load(experiment_data_file, allow_pickle=True).item()

# Iterate over each dataset and metrics
for dataset_name, data in experiment_data.items():
    print(f"Dataset: {dataset_name}")

    # Check for and print train accuracy if available
    if "train" in data["metrics"]:
        train_accuracies = data["metrics"]["train"]
        if train_accuracies:
            print(f"Train Accuracy: {train_accuracies[-1]:.4f}")

    # Check for and print validation accuracy if available
    if "val" in data["metrics"]:
        val_accuracies = data["metrics"]["val"]
        if val_accuracies:
            print(f"Validation Accuracy: {val_accuracies[-1]:.4f}")

    # Print losses if available
    for loss_type in ["train", "val"]:
        if loss_type in data["losses"]:
            losses = data["losses"][loss_type]
            if losses:
                print(f"{loss_type.capitalize()} Loss: {losses[-1]:.4f}")
